<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {httpClient} from '@/shared/http/client'
import {reviewCalculation,type ReviewLine} from './quote-review'
export interface QuoteOriginal {id:string;name:string;contentType:string}
const props=defineProps<{originals:QuoteOriginal[];lines:ReviewLine[];rate:string;readonly?:boolean}>()
const emit=defineEmits<{lines:[value:ReviewLine[]];rate:[value:string]}>()
const index=ref(0),zoom=ref(100),image=ref(''),loading=ref(false),imageError=ref('')
const selected=computed(()=>props.originals[index.value])
const calculation=computed(()=>{try{return {value:reviewCalculation(props.lines,props.rate),error:''}}catch(error){return {error:error instanceof Error?error.message:'请核对报价信息'}}})
let generation=0
function release(){if(image.value)URL.revokeObjectURL(image.value);image.value=''}
async function loadImage(){
 const request=++generation;release();imageError.value='';loading.value=false;zoom.value=100
 const file=selected.value;if(!file)return
 loading.value=true
 try{const response=await httpClient.get<Blob>(`/materials/${file.id}/download`,{responseType:'blob'});if(request===generation)image.value=URL.createObjectURL(response.data)}
 catch(error){if(request===generation)imageError.value=error instanceof Error?error.message:'原件加载失败'}
 finally{if(request===generation)loading.value=false}
}
function edit(row:number,key:keyof ReviewLine,event:Event){const lines=props.lines.map(line=>({...line}));lines[row]![key]=(event.target as HTMLInputElement).value;emit('lines',lines)}
function remove(row:number){emit('lines',props.lines.filter((_,i)=>i!==row))}
watch(()=>props.originals.map(file=>file.id).join(','),()=>{index.value=0;void loadImage()},{immediate:true})
watch(index,()=>void loadImage())
onUnmounted(()=>{generation++;release()})
</script>
<template><section class="quote-review" data-reading="原图对照核对"><div class="compare-grid">
 <section class="original-pane" aria-label="网点报价原件"><header><div><h3>报价原件</h3><span>{{ originals.length?`${index+1} / ${originals.length}`:'暂无关联原件' }}</span></div><div class="image-tools"><button aria-label="缩小原图" :disabled="!image||zoom<=100" @click="zoom=Math.max(100,zoom-25)">−</button><button :disabled="!image" aria-label="恢复适应宽度" @click="zoom=100">{{ zoom }}%</button><button aria-label="放大原图" :disabled="!image||zoom>=250" @click="zoom=Math.min(250,zoom+25)">＋</button></div></header>
 <div v-if="originals.length>1" class="image-pages" aria-label="切换报价原件"><button v-for="(file,i) in originals" :key="file.id" :aria-pressed="index===i" @click="index=i">第{{ i+1 }}张</button></div>
 <div v-if="loading" class="image-skeleton" aria-busy="true" aria-label="正在加载原件"/>
 <div v-else-if="imageError" class="image-empty" role="alert">{{ imageError }}<button @click="loadImage">重新加载</button></div>
 <div v-else-if="!selected" class="image-empty">{{ readonly?'等待网点提交报价原件':'此报价未关联可追溯原件，请向网点核对。' }}</div>
 <div v-else class="image-viewport"><img v-if="image&&selected.contentType.startsWith('image/')" :src="image" :style="{width:zoom+'%'}" :alt="`报价原件 第${index+1}张`" @error="imageError='原件无法显示，请下载核对'"/><iframe v-else-if="image" :src="image" title="报价单原件PDF"/></div>
 <a v-if="image&&selected" :href="image" :download="selected.name" class="original-download">下载当前原件</a>
 </section>
 <section class="table-pane" aria-label="报价核对表"><header><div><h3>报价核对表</h3><span>{{ readonly?'网点已提交明细':'网点已提交明细 · 可修正' }}</span></div><span>{{ lines.length }} 项</span></header>
 <div v-if="!lines.length" class="table-empty">等待网点提交识别明细</div>
 <div v-else class="table-scroll"><table><caption class="sr-only">按报价原件行序核对</caption><thead><tr><th>配件/维修项目</th><th>数量</th><th>单价</th><th>金额</th><th v-if="!readonly" class="row-action"><span class="sr-only">行操作</span></th></tr></thead><tbody><tr v-for="(line,row) in lines" :key="row"><td><input :aria-label="`第${row+1}项 配件/维修项目`" :value="line.description" :disabled="readonly" maxlength="255" @input="edit(row,'description',$event)"/></td><td><input :aria-label="`第${row+1}项 数量`" :value="line.quantity" :disabled="readonly" inputmode="numeric" @input="edit(row,'quantity',$event)"/></td><td><input :aria-label="`第${row+1}项 单价（元）`" :value="line.unitPrice" :disabled="readonly" inputmode="decimal" @input="edit(row,'unitPrice',$event)"/></td><td class="line-amount">{{ calculation.value?.amounts[row]??'—' }}</td><td v-if="!readonly" class="row-action"><button :aria-label="`删除第${row+1}项`" @click="remove(row)">×</button></td></tr></tbody></table></div>
 <button v-if="!readonly" class="add-line" @click="emit('lines',[...lines,{description:'',quantity:'1',unitPrice:''}])">添加漏识别项目</button>
 <div class="review-total"><span>核对合计</span><strong>{{ calculation.value?.base??'—' }} <small>元</small></strong></div><p class="table-note">修正另存版本，网点原报价保留。</p>
 </section></div>
 <section class="markup-bar" data-reading="加价率"><label>加价率<div class="rate-input"><input aria-label="加价率（%）" :value="rate" :disabled="readonly" inputmode="decimal" @input="emit('rate',($event.target as HTMLInputElement).value)"/><span>%</span></div></label><dl><div><dt>核对合计</dt><dd>{{ calculation.value?.base??'—' }}<small> 元</small></dd></div><div><dt>加价金额</dt><dd>{{ calculation.value?.markup??'—' }}<small> 元</small></dd></div><div class="final-total"><dt>加价后金额</dt><dd aria-live="polite">{{ calculation.value?.total??'—' }}<small> 元</small></dd></div></dl><p v-if="calculation.error&&lines.length" role="alert" class="calculation-error">{{ calculation.error }}</p></section>
</section></template>
<style scoped>
.quote-review{padding:0!important;border:0!important}.compare-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:24px;align-items:start}.original-pane,.table-pane{min-width:0;padding:0!important;border:0!important}.compare-grid header{display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:60px;border-bottom:1px solid #dce5e4;margin-bottom:12px}.compare-grid h3{font-size:16px;margin:0 0 5px}.compare-grid header span{font-size:11px;color:#5e7071}.image-tools{display:flex;flex-shrink:0;gap:3px}.image-tools button{padding:5px 7px!important;margin:0!important;font-size:11px!important}.image-pages{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.image-pages button{font-size:12px!important;margin:0!important}.image-pages button[aria-pressed=true]{background:#42685f!important;color:#fff!important}.image-viewport{max-height:640px;min-height:380px;overflow:auto;background:#edf1ef;border:1px solid #dce5e4;border-radius:6px}.image-viewport img{display:block;max-width:none;height:auto}.image-viewport iframe{width:100%;height:620px;border:0}.original-download{display:inline-block;margin-top:12px;font-size:12px;color:#365c53;text-underline-offset:3px}.image-skeleton,.image-empty{min-height:400px;background:#edf1ef;border-radius:6px}.image-skeleton{animation:fade 1.3s ease-in-out infinite alternate}.image-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:18px;text-align:center;color:#5c7070;font-size:13px}.table-empty{padding:60px 20px;text-align:center;color:#5c7070;font-size:13px;border-bottom:1px solid #dce5e4}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}th,td{border:1px solid #c9d5d1;padding:6px;text-align:left}th{background:#f1f5f3;font-weight:600;color:#35534b;height:38px}th:first-child{width:auto}th:nth-child(2){width:40px}th:nth-child(3),th:nth-child(4){width:65px}.row-action{width:20px;padding:2px;text-align:center}.row-action button{border:0!important;background:none!important;padding:2px!important;margin:0!important;color:#8b5353!important}td input{width:100%;min-width:0;box-sizing:border-box;border:1px solid transparent;border-radius:3px;padding:8px 2px;font:inherit;background:transparent;color:#20383c}td input:hover:not(:disabled){border-color:#b9cbc4}td input:focus{outline:2px solid #4b7c69;outline-offset:0;background:#fff}td:nth-child(2) input,td:nth-child(3) input,.line-amount{text-align:right;font-variant-numeric:tabular-nums}td input:disabled{opacity:1;-webkit-text-fill-color:#536a6b}.add-line{font-size:12px!important;margin:12px 0!important}.review-total{display:flex;justify-content:space-between;align-items:baseline;padding:18px 0;border-bottom:2px solid #42685f;font-size:13px}.review-total strong{font-size:20px;font-variant-numeric:tabular-nums}.review-total small{font-weight:400;font-size:12px}.table-note{font-size:11px;color:#687a74;line-height:1.6}.markup-bar{display:grid;grid-template-columns:130px minmax(0,1fr);gap:20px;align-items:end;margin-top:28px;padding:24px 0 0!important;border-top:1px solid #cbd8d2!important}.markup-bar>label{font-size:12px;display:grid;gap:8px;margin:0}.rate-input{display:flex;align-items:center;border:1px solid #b7c9c0;border-radius:6px;padding-right:12px;background:#fff}.rate-input input{width:100%;min-width:0;border:0;padding:12px;font:inherit;background:transparent;color:#20383c}.rate-input:focus-within{outline:2px solid #4b7c69}.rate-input span{font-size:13px;color:#5e7068}.markup-bar dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0}.markup-bar dt{font-size:11px;color:#5e7068;margin-bottom:10px}.markup-bar dd{font-size:18px;margin:0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.markup-bar small{font-size:11px}.final-total dd{font-weight:650;color:#275c44}.calculation-error{grid-column:1/-1;color:#a7313c;font-size:12px;margin:0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@keyframes fade{from{opacity:.5}to{opacity:1}}@media(max-width:1000px){.compare-grid{grid-template-columns:1fr}.image-viewport{max-height:540px;min-height:300px}}@media(max-width:600px){.markup-bar{grid-template-columns:1fr}.markup-bar dl{gap:8px}.markup-bar dd{font-size:16px}.image-tools{gap:2px}}@media(prefers-reduced-motion:reduce){.image-skeleton{animation:none}}
</style>
